ATL_SRC.push(['@atl/forms/writeup.js', 0, `// Fills in the Employee Corrective Action / Write-Up form (Word) from the app's write-up dialog.
// Signatures and Employee Comments stay blank — they are completed by hand when the write-up is delivered.
import { WRITEUP_PARTS } from '@atl/forms/writeup-template.js';
import { docxBuilder } from '@atl/forms/docx.js';

export const LEVELS = ['Documented Verbal', 'First Written', 'Final Written', 'Suspension', 'Termination'];
export const VIOLATIONS = ['Safety / MHE Operation', 'Policy / Procedure (SOP)', 'Attendance / Tardiness', 'Conduct / Behavior',
  'Food Safety / GMP / SQF', 'Inventory / Quality Error', 'Product / Equip. Damage', 'Other'];
/** Write-up level → Disciplinary Log "Action Level". */
export const LEVEL_TO_ACTION = { 'Documented Verbal': 'Verbal Warning', 'First Written': 'Written Warning', 'Final Written': 'Final Written Warning', Suspension: 'Suspension', Termination: 'Termination' };
/** Violation type → Disciplinary Log "Category". */
export const VIOLATION_TO_CATEGORY = { 'Safety / MHE Operation': 'Safety', 'Policy / Procedure (SOP)': 'Policy / SOP Violation', 'Attendance / Tardiness': 'Attendance',
  'Conduct / Behavior': 'Conduct / Behavior', 'Food Safety / GMP / SQF': 'Food Safety / SQF', 'Inventory / Quality Error': 'Quality / Mispick',
  'Product / Equip. Damage': 'Equipment / Property Damage', Other: 'Other' };

const build = docxBuilder(WRITEUP_PARTS);
const us = iso => (iso ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(0, 4)}\` : '');
const t12 = hhmm => { if (!hhmm) return ''; const [h, m] = hhmm.split(':').map(Number); return \`\${((h + 11) % 12) + 1}:\${String(m).padStart(2, '0')} \${h < 12 ? 'AM' : 'PM'}\`; };

/**
 * w: { name, employeeId, jobTitle, shift, facility, manager, date (ISO), incidentDate (ISO), incidentTime 'HH:MM',
 *      level (LEVELS), suspensionDays, violations: [VIOLATIONS], otherViolation, summary, policy,
 *      prior: 'None' | 'Yes', priorText, action, refId } → Blob (.docx)
 */
export function writeUpDocx(w) {
  return build(({ table, after, box, put, tick, clear }) => {
    const info = table('Employee Name:');
    put(after(info, 'Employee Name:'), w.name);
    put(after(info, 'Employee ID:'), w.employeeId);
    put(after(info, 'Job Title:'), w.jobTitle);
    put(after(info, 'Shift:'), w.shift);
    put(after(info, 'Facility / Location:'), w.facility);
    put(after(info, 'Supervisor / Manager:'), w.manager);
    put(after(info, 'Date of Write-Up:'), us(w.date));
    put(after(info, 'Date & Time of Incident:'), [us(w.incidentDate), t12(w.incidentTime)].filter(Boolean).join(' @ '));

    const level = table('LEVEL OF CORRECTIVE ACTION');
    if (w.level === 'Suspension') tick(level, 'Suspension', \`☒ Suspension: \${w.suspensionDays ? \`\${w.suspensionDays} day\${+w.suspensionDays === 1 ? '' : 's'}\` : '____ day(s)'}\`);
    else tick(level, w.level);

    const types = table('☐ Safety / MHE Operation');
    for (const v of w.violations || []) v === 'Other' ? tick(types, 'Other', \`☒ Other: \${w.otherViolation || '____________'}\`) : tick(types, v);

    put(box(table('INCIDENT SUMMARY')), w.summary);
    const pol = table('Policy / SOP Violated:');
    if (w.policy) { const c = after(pol, 'Policy / SOP Violated:'); clear(c); put(c, w.policy); }
    if (w.prior === 'Yes') tick(pol, 'Yes', \`☒ Yes — Date(s) / Level: \${w.priorText || '____________________________'}\`);
    else if (w.prior === 'None') tick(pol, 'None');
    put(box(table('DISCIPLINARY ACTION & EXPECTED IMPROVEMENT')), [w.action, w.refId ? \`(Disciplinary Log \${w.refId})\` : ''].filter(Boolean));
  });
}

/** "DOE, JANE – Write-Up – 2026-01-15.docx" style file name. */
export function writeUpFileName(w) {
  const n = String(w.name).trim().split(/\\s+/), name = n.length > 1 ? \`\${n.slice(1).join(' ')}, \${n[0]}\` : n[0];
  return \`\${name} – Write-Up – \${w.date}.docx\`.replace(/[\\\\/:*?"<>|]/g, '-');
}`]);

