ATL_SRC.push(['@atl/goaudits.js', 0, `// GoAudits drops (Nov 2026, from Josh): WestRock Arrival Condition Reports and Electrolit receiving audits (OS&D) can be
// dropped together — PDFs or the GoAudits emails, many at once, on either scorecard's drop (or anywhere in the app).
// Each one is read and sorted: an Electrolit audit says "Electrolit"; a WestRock ACR has the WestRock business units
// ("NOR - NORCROSS XDK", …). WestRock ACRs post to the WestRock scorecard (wrAcr), Electrolit audits to the Electrolit
// scorecard as NCRs (elxNcr).
// Speed (Nov 2026): each PDF is read once (hrpdf.js ▸ pdfTextItemsOf), several files are read and posted at a time,
// and a report's PDF is saved under a fixed id (ACR-<ref>-pdf / NCR-<ref>-pdf) — so posting never has to load every
// attachment in the database to find the old copy (that was what made big drops crawl).
import { store } from '@atl/store.js';
import { readAcr, BUILDING as WR_BUILDING } from '@atl/westrock.js';
import { readNcr } from '@atl/electrolit.js';
import { unpackEmails } from '@atl/railnotify.js';
import { files, prepFile } from '@atl/forms/incident.js';

const PART = 700000; // base64 characters per stored part (same as Safety Incident attachments)
/** Run fn over the list, \`limit\` at a time; results in the list's order. */
async function pool(list, limit, fn) {
  const out = new Array(list.length); let i = 0;
  await Promise.all(Array.from({ length: Math.min(limit, list.length) }, async () => { while (i < list.length) { const k = i++; out[k] = await fn(list[k], k); } }));
  return out;
}

/** Read and sort the dropped files → { acr: [report], ncr: [report], fileOf: { 'acr:ref' | 'ncr:ref': File }, errors }. */
export async function sortAudits(list) {
  const un = await unpackEmails([...list]), errors = [...(un.errors || [])], acr = [], ncr = [], fileOf = {};
  const read = await pool(un.files, 4, async f => {
    try { return { f, kind: 'acr', r: await readAcr(f) }; } catch { /* not a WestRock ACR */ }
    try { return { f, kind: 'ncr', r: await readNcr(f) }; } catch { /* not an Electrolit audit */ }
    return { f, kind: '' };
  });
  for (const { f, kind, r } of read) {
    if (!kind) { errors.push(\`\${f.name}: not a WestRock ACR or an Electrolit audit (OS&D).\`); continue; }
    const into = kind === 'acr' ? acr : ncr;
    if (into.some(x => x.ref === r.ref)) continue;
    into.push(r); fileOf[\`\${kind}:\${r.ref}\`] = f;
  }
  const byDate = (a, b) => String(a.date).localeCompare(String(b.date));
  return { acr: acr.sort(byDate), ncr: ncr.sort(byDate), fileOf, errors };
}

/** Save a report's PDF under a fixed id (replacing the copy posted before), without listing other attachments. */
async function savePdf(fid, file) {
  const f = await prepFile(file);
  if (store.demo) return files.add(fid, f);
  const id = \`\${fid}-pdf\`, data = String(f.data || ''), n = Math.max(1, Math.ceil(data.length / PART));
  const old = await store.get('incidentFiles', id).catch(() => null);
  await Promise.all(Array.from({ length: n - 1 }, (_, k) => store.set('incidentFiles', \`\${id}__\${k + 1}\`, { partOf: id, part: k + 1, data: data.slice((k + 1) * PART, (k + 2) * PART) })));
  await store.set('incidentFiles', id, { incidentId: fid, name: f.name, type: f.type, size: f.size, data: data.slice(0, PART), ...(n > 1 ? { parts: n } : {}), addedAt: new Date().toISOString(), addedBy: store.user?.email || '' });
  for (let p = n; p < (old?.parts || 1); p++) await store.remove('incidentFiles', \`\${id}__\${p}\`).catch(() => {});
}

const meta = () => ({ postedAt: new Date().toISOString(), postedBy: store.user?.name || store.user?.email || '' });
/** Post WestRock ACRs (and their PDFs), several at a time. */
export async function postAcrs(list, fileOf = {}) {
  const m = { ...meta(), customer: 'WestRock', facility: WR_BUILDING };
  await pool(list, 4, async r => {
    await store.set('wrAcr', r.ref, { ...r, ...m });
    const f = fileOf[\`acr:\${r.ref}\`];
    if (f) await savePdf(\`ACR-\${r.ref}\`, f);
  });
}
/** Post Electrolit audits as NCRs (and their PDFs), several at a time. category(r) → the category to keep (the review screen's pick). */
export async function postNcrs(list, fileOf = {}, category = r => r.category) {
  const m = meta(), cats = new Map(list.map(r => [r.ref, category(r)])); // read the picks before anything re-renders
  await pool(list, 4, async r => {
    await store.set('elxNcr', r.ref, { ...r, category: cats.get(r.ref), ...m });
    const f = fileOf[\`ncr:\${r.ref}\`];
    if (f) await savePdf(\`NCR-\${r.ref}\`, f);
  });
}`]);

