ATL_SRC.push(['@atl/libdocs.js', 0, `// Records filed in SOP / Documents from the app (Nov 2026): scanned training handouts and sign-in sheets, and any other
// uploaded record kept in a library folder. The list lives in "libDocs" (one small record per file: folder, title,
// file name, size, category, what it belongs to, history); the file itself is in "libFiles", split into ~700 KB parts
// (Firestore allows ~1 MB per document). Demo mode keeps the parts in this browser's IndexedDB.
// moveRecord(): any uploaded library record — these and the MHE inspection checklists (mheDocs) — can be moved to
// another folder when it was filed in the wrong one; the move is written to the record's history.
import { store } from '@atl/store.js';
import { downloadBlob } from '@atl/util.js';
import { remember, locOf } from '@atl/locate.js';

const PART = 700000;
let dbp;
const db = () => (dbp ||= new Promise((res, rej) => {
  const r = indexedDB.open('atl-ops-lib-files', 1);
  r.onupgradeneeded = () => r.result.createObjectStore('parts', { keyPath: 'id' });
  r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
}));
const idb = async (mode, fn) => { const d = await db(); return new Promise((res, rej) => { const t = d.transaction('parts', mode), q = fn(t.objectStore('parts')); t.oncomplete = () => res(q?.result); t.onerror = () => rej(t.error); t.onabort = () => rej(t.error); }); };
const b64 = async blob => { const u = new Uint8Array(await blob.arrayBuffer()); let s = ''; for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode(...u.subarray(i, i + 0x8000)); return btoa(s); };
const who = () => store.user?.name || store.user?.email || '';

/** Save a file into a library folder. meta: { folder, title, category, ...anything to keep with it }. Returns the id. */
export async function addLibDoc(file, meta) {
  const data = await b64(file), n = Math.max(1, Math.ceil(data.length / PART));
  const id = 'L' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), now = new Date().toISOString();
  remember(id, locOf('libDocs', meta)); // the parts are saved first: they take the record's location
  for (let p = 0; p < n; p++) {
    const part = { docId: id, part: p, data: data.slice(p * PART, (p + 1) * PART) };
    if (store.demo) await idb('readwrite', s => s.put({ id: \`\${id}|\${p}\`, ...part }));
    else await store.set('libFiles', \`\${id}__\${p}\`, part);
  }
  await store.set('libDocs', id, { ...meta, name: file.name, type: file.type || 'application/pdf', size: file.size, parts: n, addedAt: now, addedBy: who(), history: [{ at: now, by: who(), what: \`Filed in \${meta.folder}\` }] });
  return id;
}
export async function libBlob(rec) {
  let s = '';
  for (let p = 0; p < (rec.parts || 1); p++) {
    const d = store.demo ? await idb('readonly', o => o.get(\`\${rec.id}|\${p}\`)) : await store.get('libFiles', \`\${rec.id}__\${p}\`);
    if (!d) throw new Error(\`Part of \${rec.name} is missing.\`);
    s += d.data;
  }
  return new Blob([Uint8Array.from(atob(s), c => c.charCodeAt(0))], { type: rec.type || 'application/pdf' });
}
export async function openLib(rec) { const b = await libBlob(rec), u = URL.createObjectURL(b); if (!window.open(u, '_blank')) downloadBlob(rec.name, b); setTimeout(() => URL.revokeObjectURL(u), 60000); }
export async function saveLib(rec) { downloadBlob(rec.name, await libBlob(rec)); }
export async function removeLibDoc(rec) {
  for (let p = 0; p < (rec.parts || 1); p++) { if (store.demo) await idb('readwrite', o => o.delete(\`\${rec.id}|\${p}\`)); else await store.remove('libFiles', \`\${rec.id}__\${p}\`).catch(() => {}); }
  await store.remove('libDocs', rec.id);
}

/**
 * Move a filed record to another folder ("Training/6049/2027/January"). kind: 'lib' (libDocs) or 'mhe' (an MHE
 * inspection checklist in mheDocs). Keeps a note in the record's history.
 */
export async function moveRecord(kind, rec, folder) {
  folder = String(folder || '').split('/').map(s => s.trim()).filter(Boolean).join('/');
  if (!folder) throw new Error('Choose the folder to move it to.');
  const now = new Date().toISOString(), from = kind === 'mhe' ? rec.libFolder : rec.folder;
  if (from === folder) return;
  const history = [...(rec.history || []), { at: now, by: who(), what: \`Moved from \${from || '—'} to \${folder}\` }];
  if (kind === 'mhe') await store.update('mheDocs', rec.id, { libFolder: folder, history });
  else await store.update('libDocs', rec.id, { folder, history });
}
/** A file name not already used in that folder: "Name.pdf", then "Name (2).pdf", … */
export function freeName(folder, name) {
  const used = new Set(store.rows('libDocs').filter(d => d.folder === folder).map(d => String(d.name).toLowerCase()));
  if (!used.has(name.toLowerCase())) return name;
  const base = name.replace(/\\.pdf$/i, '');
  for (let k = 2; ; k++) { const n = \`\${base} (\${k}).pdf\`; if (!used.has(n.toLowerCase())) return n; }
}`]);

